/**
 * @suppress
 */
public object FfiConverterTypeKtNode: FfiConverter<KtNode, Long> {
    override fun lower(value: KtNode): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): KtNode {
        return KtNode(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): KtNode {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: KtNode) = 8UL

    override fun write(value: KtNode, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



