sealed class KtException: kotlin.Exception() {
    
    class Failed(
        
        val `msg`: kotlin.String
        ) : KtException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<KtException> {
        override fun lift(error_buf: RustBuffer.ByValue): KtException = FfiConverterTypeKtError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeKtError : FfiConverterRustBuffer<KtException> {
    override fun read(buf: ByteBuffer): KtException {
        

        return when(buf.getInt()) {
            1 -> KtException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: KtException): ULong {
        return when(value) {
            is KtException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: KtException, buf: ByteBuffer) {
        when(value) {
            is KtException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




enum class Platform {
    
    DESKTOP,
    PHONE;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypePlatform: FfiConverterRustBuffer<Platform> {
    override fun read(buf: ByteBuffer) = try {
        Platform.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: Platform) = 4UL

    override fun write(value: Platform, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




